export function sampleAcrossTime(records,limit=24){if(records.length<=limit)return [...records];if(limit<2)return [records[0]];return Array.from({length:limit},(_,i)=>records[Math.round(i*(records.length-1)/(limit-1))]);}
export function quantiles(values){const a=values.filter(Number.isFinite).sort((x,y)=>x-y);if(!a.length)return {low:0,high:1,median:0};const q=p=>a[Math.floor((a.length-1)*p)];return {low:q(.02),high:q(.995),median:q(.5)};}
export function validPixels(frame,mask=true){return frame.pixels.map((v,i)=>v===null||(mask&&frame.mask?.[i])?NaN:v);}
export function canDifference(a,b){return Number.isFinite(a?.wavelength)&&Number.isFinite(b?.wavelength)&&Number.isFinite(a?.bandwidth)&&Number.isFinite(b?.bandwidth)&&Math.abs(a.wavelength-b.wavelength)<=(a.bandwidth+b.bandwidth)/2;}
export function differencePixels(a,b,mask=true){if(a.width!==b.width||a.height!==b.height)throw new Error('Images must share the same sky grid.');if(!canDifference(a,b))throw new Error('Central bandpasses do not overlap. Select a similar-wavelength comparison.');const x=validPixels(a,mask),y=validPixels(b,mask),xm=quantiles(x).median,ym=quantiles(y).median;return x.map((v,i)=>Number.isFinite(v)&&Number.isFinite(y[i])?(v-xm)-(y[i]-ym):NaN);}
